function card(string $n,string $price,string $desc,array $items,bool $featured=false):void{
 echo '<article class="price-card'.($featured?' featured':'').'">'.($featured?'<span class="popular">MOST POPULAR</span>':'').'<p class="eyebrow">'.$n.'</p><h3>'.$price.'<small>'.($price==='Custom'?'':' /mo').'</small></h3><p class="muted">'.$desc.'</p><a class="button '.($featured?'button-accent':'button-outline').'" href="'.($n==='Custom'?'mailto:sales@fyndet.com?subject=FyndEt%20Custom%20Plan':'/register').'">'.($n==='Custom'?'Contact sales':'Get started').' <span>↗</span></a><ul>';
 foreach($items as $i)echo '<li><span class="tick">✓</span>'.esc($i).'</li>';echo '</ul></article>';
